"use client"

import * as React from "react"
import { Sign, type SignProps } from "@/components/ui/sign"
import type { SignShape } from "@/lib/0db/sign-shapes"

const shape: SignShape = {
  "word": "search",
  "line": [
    [
      [
        "O",
        10,
        10,
        6.5,
        180,
        360
      ]
    ],
    [
      [
        "M",
        15.6,
        15.6
      ],
      [
        "L",
        21.5,
        21.5
      ]
    ]
  ]
}

function SignSearchDots(props: Omit<SignProps, "shape" | "variant">) {
  return <Sign shape={shape} variant="dots" {...props} />
}

export { SignSearchDots, shape }
